'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { Activity, Lock, Mail, ArrowRight, User } from 'lucide-react';
import { Input } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';
import { Card } from '@/components/ui/Card';
import { createSupabaseBrowserClient, isLiveSupabase } from '@/lib/supabase/client';

const signupSchema = z.object({
  fullName: z.string().min(1, 'Name is required'),
  email: z.string().min(1, 'Email is required').email('Invalid email address'),
  password: z.string().min(6, 'Password must be at least 6 characters'),
});

type SignupValues = z.infer<typeof signupSchema>;

export default function SignupPage() {
  const router = useRouter();
  const [authError, setAuthError] = useState<string | null>(null);

  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<SignupValues>({
    resolver: zodResolver(signupSchema),
    defaultValues: {
      fullName: '',
      email: '',
      password: '',
    },
  });

  const onSubmit = async (values: SignupValues) => {
    try {
      setAuthError(null);

      if (isLiveSupabase()) {
        const supabase = createSupabaseBrowserClient();
        const { error } = await supabase.auth.signUp({
          email: values.email,
          password: values.password,
          options: {
            data: {
              full_name: values.fullName,
            },
          },
        });

        if (error) {
          setAuthError(error.message);
          return;
        }
      } else {
        // Local dev simulation
        const mockUser = { id: `usr_${Date.now()}`, email: values.email };
        localStorage.setItem('pingwatch_user', JSON.stringify(mockUser));
        localStorage.setItem('pingwatch_demo_token', 'demo-bearer-token');
        document.cookie = 'pingwatch_auth=true; path=/; max-age=86400';
      }

      router.push('/dashboard');
    } catch (err: any) {
      setAuthError(err.message || 'Failed to sign up');
    }
  };

  return (
    <div className="min-h-screen bg-[#0D1117] flex flex-col justify-center py-12 px-6 lg:px-8 selection:bg-[#00FF87]/30 selection:text-[#00FF87]">
      <div className="sm:mx-auto sm:w-full sm:max-w-md text-center">
        <Link href="/" className="inline-flex items-center gap-2 mb-4">
          <div className="w-8 h-8 rounded-[6px] bg-[#00FF87]/15 border border-[#00FF87]/40 flex items-center justify-center text-[#00FF87]">
            <Activity className="h-4 w-4" />
          </div>
          <span className="font-bold tracking-tight font-mono text-xl text-white">
            Ping<span className="text-[#00FF87]">Watch</span>
          </span>
        </Link>
        <h2 className="text-2xl font-bold tracking-tight text-white">
          Create your PingWatch account
        </h2>
        <p className="mt-2 text-xs text-[#8B949E]">
          Already have an account?{' '}
          <Link href="/auth/login" className="text-[#00FF87] hover:underline">
            Sign in
          </Link>
        </p>
      </div>

      <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-md">
        <Card className="bg-[#161B22] border-[#30363D] p-6 shadow-xl">
          <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
            {authError && (
              <div className="p-3 text-xs bg-[#FF4D4F]/10 border border-[#FF4D4F]/30 text-[#FF4D4F] rounded-[6px]">
                {authError}
              </div>
            )}

            <div>
              <label className="block text-xs font-medium text-[#8B949E] mb-1 flex items-center gap-1.5">
                <User className="h-3.5 w-3.5" /> Full name
              </label>
              <Input
                id="fullName"
                type="text"
                placeholder="Alex Morgan"
                error={errors.fullName?.message}
                {...register('fullName')}
              />
            </div>

            <div>
              <label className="block text-xs font-medium text-[#8B949E] mb-1 flex items-center gap-1.5">
                <Mail className="h-3.5 w-3.5" /> Email address
              </label>
              <Input
                id="email"
                type="email"
                placeholder="alex@example.com"
                error={errors.email?.message}
                {...register('email')}
              />
            </div>

            <div>
              <label className="block text-xs font-medium text-[#8B949E] mb-1 flex items-center gap-1.5">
                <Lock className="h-3.5 w-3.5" /> Password
              </label>
              <Input
                id="password"
                type="password"
                placeholder="••••••••"
                error={errors.password?.message}
                {...register('password')}
              />
            </div>

            <Button type="submit" variant="primary" className="w-full mt-2" isLoading={isSubmitting}>
              Create Free Account <ArrowRight className="h-4 w-4 ml-1" />
            </Button>
          </form>
        </Card>
      </div>
    </div>
  );
}
